const samples = await IO.loadMNIST();
const pca = PCA.new(samples, 16)

const image = IO.paintMNIST(new Float32Array(pca.mean.toArray()));
const updateImage = image.update;
let pcaCoords = [0,0,0];
const exploreUI = IO.UI(
    {type: "canvas", value: () => image},
    {type: "slider", value: () => ({
        min: -1,
        max: 1,
        title: "alpha_1",
        onChange: value => {
            pcaCoords[0] = value
            updateImage(new Float32Array(pca.gen(pcaCoords).toArray()))
        },
    })},
    {type: "slider", value: () => ({
        min: -1,
        max: 1,
        title: "alpha_2",
        onChange: value => {
            pcaCoords[1] = value
            updateImage(new Float32Array(pca.gen(pcaCoords).toArray()))
        },
    })},
    {type: "slider", value: () => ({
        min: -1,
        max: 1,
        title: "alpha_3",
        onChange: value => {
            pcaCoords[2] = value
            updateImage(new Float32Array(pca.gen(pcaCoords).toArray()))
        },
    })
  })
exploreUI;
